function buildProjects(): Project[] {
  const sections: Array<[string, Project["category"], Omit<Project, "id" | "category">[]]> = [
    ["saas", "saas", SAAS],
    ["creative", "creative", CREATIVE],
    ["utility", "utility", UTILITY],
    ["social", "social", SOCIAL],
    ["deeptech", "deeptech", DEEPTECH],
  ];

  const out: Project[] = [];
  for (const [prefix, category, list] of sections) {
    list.forEach((p, i) => {
      out.push({
        id: `${prefix}-${String(i + 1).padStart(3, "0")}`,
        category,
        ...p,
      });
    });
  }
  return out;
}

export const PROJECTS: Project[] = buildProjects();
